begin;
create extension if not exists pgtap with schema extensions;
select plan(10);
select is((select jsonb_array_length(questions) from lms.assessment_config),20,'all twenty supplied questions published');
select ok((select approved from lms.assessment_config),'complete translated questionnaire is active');
select is((select count(distinct question->>'id')::integer from lms.assessment_config,jsonb_array_elements(questions) question),20,'question IDs are unique');
select ok((select bool_and(jsonb_array_length(question->'options')=3) from lms.assessment_config,jsonb_array_elements(questions) question),'every question has three options');
insert into auth.users(id,email) values('70000000-0000-0000-0000-000000000001','full-assessment@example.test'),('70000000-0000-0000-0000-000000000002','tie-assessment@example.test');
set local role authenticated;
select set_config('request.jwt.claim.sub','70000000-0000-0000-0000-000000000001',true);
select is((lms.save_assessment('{"ep-01":0}')->>'completed')::boolean,false,'partial answer stays draft');
select is((lms.save_assessment((select jsonb_object_agg(question->>'id',0) from lms.assessment_config,jsonb_array_elements(questions) question))->>'completed')::boolean,true,'full questionnaire completes');
select is((select original_style from lms.assessment_results where student_id=auth.uid()),'visual','visual responses set original preference');
select is((select scores from lms.assessment_results where student_id=auth.uid()),'{"visual":20,"auditory":0,"kinesthetic":0}'::jsonb,'one point per question');
select set_config('request.jwt.claim.sub','70000000-0000-0000-0000-000000000002',true);
select throws_ok($$select lms.save_assessment('{"ep-01":3}')$$,'P0001','Invalid assessment choice','forged choice rejected');
select is(lms.save_assessment((select jsonb_object_agg(question->>'id',case when ordinal<=10 then 0 else 1 end) from lms.assessment_config,jsonb_array_elements(questions) with ordinality as item(question,ordinal)))->'tied_styles','["auditory","visual"]'::jsonb,'twenty-question tie needs explicit preference');
select * from finish();
rollback;
